def simulate_v3(c_list):
    # I_n = union of (a_i, b_i)
    # I_0 = (0, 1)
    intervals = [(0, 1)]
    for c in c_list:
        # S_cw = {x \in I_n | x < 1-c and x+c \in I_n}
        # S_ccw = {x \in I_n | x > c and x-c \in I_n}
        # I_{n+1} = S_cw \cup S_ccw

        # To compute S_cw:
        # x \in I_n \cap (0, 1-c) and x \in (I_n - c)
        # I_n - c = union of (a_i-c, b_i-c)

        # Let's just compute I_n - c and I_n + c
        minus_c = []
        for a, b in intervals:
            minus_c.append((a-c, b-c))
        minus_c = get_intervals_union(minus_c)

        plus_c = []
        for a, b in intervals:
            plus_c.append((a+c, b+c))
        plus_c = get_intervals_union(plus_c)

        s_cw = []
        for a1, b1 in intervals:
            for a2, b2 in minus_c:
                start = max(a1, 0, a2)
                end = min(b1, 1-c, b2)
                if start < end:
                    s_cw.append((start, end))

        s_ccw = []
        for a1, b1 in intervals:
            for a2, b2 in plus_c:
                start = max(a1, c, a2)
                end = min(b1, 1, b2)
                if start < end:
                    s_ccw.append((start, end))

        intervals = get_intervals_union(s_cw + s_ccw)
        if not intervals:
            return False
    return True

