def can_avoid(c_list):
    intervals = [(0, 1)]
    for c in c_list:
        new_intervals = []
        for a, b in intervals:
            new_intervals.append((a + c, b + c))
            new_intervals.append((a - c, b - c))
        final_intervals = []
        for a, b in new_intervals:
            start = max(a, 0)
            end = min(b, 1)
            if start < end:
                final_intervals.append((start, end))
        final_intervals.sort()
        merged = []
        if final_intervals:
            curr_a, curr_b = final_intervals[0]
            for i in range(1, len(final_intervals)):
                a, b = final_intervals[i]
                if a < curr_b:
                    curr_b = max(curr_b, b)
                else:
                    merged.append((curr_a, curr_b))
                    curr_a, curr_b = a, b
            merged.append((curr_a, curr_b))
        intervals = merged
        if not intervals:
            return False
    return True

